<!DOCTYPE html>
<html lang="id" data-lang="id">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>PT. SNI | Ultimate Welding Materials for Special Applications</title>
<meta name="description" content="PT. Seoul Nikko Indonesia: distributor resmi NICHIA, Nikkei Aluminium, KISWEL, Hyundai Welding, Harris, dan Kennametal. Kawat las khusus dan suku cadang pembangkit listrik di Jakarta sejak 2007.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Archivo:wdth,wght@62..125,300..900&family=Noto+Sans+JP:wght@400;500;700;800&family=Noto+Sans+KR:wght@400;500;700;800&display=swap" rel="stylesheet">
<style>
:root{
  --ink:#17212B;
  --ink-soft:#4A5662;
  --steel:#F3F5F6;
  --plate:#E4E9ED;
  --rule:#CBD3DA;
  --scale:#1D2934;
  --scale-2:#26343F;
  --brand:#0A3A82;
  --blue:#2F5E9E;
  --violet:#5B4A94;
  --bronze:#A8683A;
  --straw:#D8A64A;
  --font:"Archivo","Helvetica Neue",Arial,sans-serif;
  --wrap:1180px;
}
html[data-lang="ko"]{--font:"Archivo","Noto Sans KR","Apple SD Gothic Neo","Malgun Gothic",sans-serif}
html[data-lang="ja"]{--font:"Archivo","Noto Sans JP","Hiragino Sans","Yu Gothic",sans-serif}
*{box-sizing:border-box}
html{scroll-behavior:smooth;scroll-padding-top:84px}
body{margin:0;background:var(--steel);color:var(--ink);font-family:var(--font);font-size:17px;line-height:1.6;-webkit-font-smoothing:antialiased}
html[data-lang="ko"] body{word-break:keep-all}
html[data-lang="ja"] body{line-break:strict}
a{color:inherit}
img{max-width:100%}
:focus-visible{outline:3px solid var(--blue);outline-offset:3px;border-radius:2px}
.wrap{max-width:var(--wrap);margin:0 auto;padding:0 28px}

/* top bar */
.topbar{background:var(--scale);color:#C9D2DA;font-size:14px}
.topbar .wrap{display:flex;justify-content:space-between;align-items:center;gap:16px;min-height:40px}
.topbar a{text-decoration:none}
.topbar a:hover{color:#fff}
.lang{display:flex;gap:2px;flex-wrap:wrap}
.lang button{font-family:"Archivo","Noto Sans KR","Noto Sans JP",sans-serif;font-size:13px;font-weight:600;background:none;border:1px solid transparent;color:#C9D2DA;padding:3px 10px;border-radius:3px;cursor:pointer}
.lang button[aria-pressed="true"]{border-color:#6B7A87;color:#fff}

/* header */
header.site{position:sticky;top:0;z-index:20;background:#fff;border-bottom:1px solid var(--rule)}
header.site .wrap{display:flex;align-items:center;justify-content:space-between;gap:24px;min-height:72px}
.brand{display:flex;align-items:center}
.brand img{height:40px;width:auto;display:block}
nav.main ul{list-style:none;display:flex;gap:26px;margin:0;padding:0}
nav.main a{text-decoration:none;font-weight:500;font-size:15.5px;color:var(--ink-soft)}
nav.main a:hover{color:var(--ink)}
.btn{display:inline-flex;align-items:center;gap:10px;font:inherit;font-weight:650;font-size:15.5px;text-decoration:none;padding:13px 22px;border-radius:4px;border:1.5px solid var(--ink);cursor:pointer;transition:background .15s,color .15s,border-color .15s}
.btn-solid{background:var(--brand);border-color:var(--brand);color:#fff}
.btn-solid:hover{background:var(--ink);border-color:var(--ink)}
.btn-line{background:transparent;color:var(--ink)}
.btn-line:hover{background:var(--ink);color:#fff}
.menu-toggle{display:none;font:inherit;background:none;border:1.5px solid var(--ink);border-radius:4px;padding:8px 12px;font-weight:600;cursor:pointer}

/* hero */
.hero{padding:88px 0 0}
.hero h1{font-stretch:112%;font-weight:800;font-size:clamp(38px,6vw,78px);line-height:1.02;letter-spacing:-.025em;margin:0;max-width:17ch}
html[data-lang="ko"] .hero h1,html[data-lang="ja"] .hero h1{letter-spacing:-.01em;line-height:1.2;max-width:14em}
.hero .lead{font-size:clamp(17px,1.6vw,20px);color:var(--ink-soft);max-width:56ch;margin:28px 0 36px}
html[data-lang="ko"] .hero .lead,html[data-lang="ja"] .hero .lead{max-width:38em}
.hero .actions{display:flex;flex-wrap:wrap;gap:14px}
.bead-wrap{margin-top:80px;height:64px;overflow:hidden;animation:weld 1.8s cubic-bezier(.55,.1,.3,1) .25s both}
.bead-wrap svg{display:block;width:100%;height:64px}
@keyframes weld{from{clip-path:inset(0 100% 0 0)}to{clip-path:inset(0 0 0 0)}}

/* brands */
.brands{padding:34px 0 72px}
.brands .wrap{display:grid;grid-template-columns:200px 1fr;gap:32px;align-items:center}
.brands p{margin:0;font-size:15px;color:var(--ink-soft)}
.brands ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:12px 40px}
.brands li{font-family:"Archivo",sans-serif;font-weight:750;font-stretch:118%;font-size:clamp(19px,2.1vw,26px);letter-spacing:-.01em}

/* section base */
section.block{padding:96px 0}
.head{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,6fr);gap:48px;align-items:end;margin-bottom:56px}
.head h2{font-stretch:110%;font-weight:800;font-size:clamp(32px,4vw,52px);line-height:1.08;letter-spacing:-.02em;margin:0}
html[data-lang="ko"] .head h2,html[data-lang="ja"] .head h2{letter-spacing:-.01em;line-height:1.2}
.head p{margin:0;color:var(--ink-soft);max-width:58ch}

/* products */
#produk{background:#fff;border-top:1px solid var(--rule);border-bottom:1px solid var(--rule)}
.catalog{display:grid;grid-template-columns:3fr 2fr;gap:56px}
.catalog h3{font-size:19px;font-weight:700;margin:0 0 10px;padding-bottom:12px;border-bottom:2px solid var(--ink)}
.catalog dl{margin:0}
.catalog .row{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.25fr);gap:20px;padding:15px 0;border-bottom:1px solid var(--rule)}
.catalog dt{font-weight:650}
.catalog dd{margin:0;color:var(--ink-soft);font-size:15.5px}
.catalog .single .row{grid-template-columns:1fr}
.catalog .single dd{margin-top:2px}

/* power plant */
#pembangkit{background:var(--scale);color:#E6ECF1}
#pembangkit .head p{color:#AFBBC6}
#pembangkit h3{font-size:17px;font-weight:650;color:#fff;margin:0 0 18px}
.parts{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));column-gap:28px;border-top:1px solid #3A4854}
.parts li{padding:18px 0;border-bottom:1px solid #3A4854}
.parts li b{display:block;font-weight:650;color:#fff}
.parts li span{font-size:14.5px;color:#9EABB7}

/* industries */
.hint{margin:0 0 16px;font-size:15px;color:var(--ink-soft)}
.sectors{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:10px}
.sector{display:inline-block;font:inherit;font-size:15px;border:1px solid var(--rule);background:#fff;color:var(--ink);border-radius:40px;padding:8px 18px;line-height:1.3}
button.sector{cursor:pointer;border-color:#9AA7B3;font-weight:550}
button.sector:hover{border-color:var(--brand);color:var(--brand)}
button.sector[aria-pressed="true"]{background:var(--brand);border-color:var(--brand);color:#fff}
.sector.static{color:#8A96A1;background:transparent}
.clients{margin-top:28px;background:#fff;border:1px solid var(--rule);border-top:3px solid var(--brand);padding:24px 28px;min-height:118px}
.clients h3{margin:0 0 14px;font-size:15px;font-weight:600;color:var(--ink-soft)}
.clients h3 b{color:var(--ink)}
.clients ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:10px 40px}
.clients li{font-family:"Archivo",sans-serif;font-size:clamp(20px,2.2vw,26px);font-weight:750;font-stretch:112%;letter-spacing:-.01em}

/* about */
#tentang{background:#fff;border-top:1px solid var(--rule)}
.about{display:grid;grid-template-columns:minmax(0,5fr) minmax(0,6fr);gap:64px}
.about h2{font-stretch:110%;font-weight:800;font-size:clamp(32px,4vw,52px);line-height:1.08;letter-spacing:-.02em;margin:0}
.vision{margin:28px 0 0;font-stretch:108%;font-weight:700;font-size:clamp(22px,2.4vw,30px);line-height:1.3;letter-spacing:-.01em;color:var(--brand);max-width:22ch}
html[data-lang="ko"] .vision,html[data-lang="ja"] .vision{max-width:16em;line-height:1.45}
.pledges{list-style:none;margin:0;padding:0;border-top:2px solid var(--ink)}
.pledges li{padding:22px 0;border-bottom:1px solid var(--rule)}
.pledges b{display:block;font-size:19px;font-weight:700;margin-bottom:6px}
.pledges p{margin:0;color:var(--ink-soft);max-width:58ch}

/* contact */
#kontak{background:var(--steel)}
.contact{display:grid;grid-template-columns:minmax(0,6fr) minmax(0,5fr);gap:64px;align-items:start}
.contact h2{font-stretch:110%;font-weight:800;font-size:clamp(32px,4vw,52px);line-height:1.08;letter-spacing:-.02em;margin:0 0 18px}
.contact .lead{color:var(--ink-soft);margin:0 0 30px;max-width:48ch}
.contact .actions{display:flex;flex-wrap:wrap;gap:14px}
.info{border-top:2px solid var(--ink);margin:0}
.info div{padding:16px 0;border-bottom:1px solid var(--rule);display:grid;grid-template-columns:110px 1fr;gap:16px}
.info dt{color:var(--ink-soft);font-size:15px}
.info dd{margin:0;font-weight:500}
.info a{text-decoration-thickness:1px;text-underline-offset:3px}

footer{background:var(--scale);color:#9EABB7;font-size:14px;padding:28px 0}
footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}

/* responsive */
@media (max-width:1060px){.parts{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:960px){
  nav.main{display:none;position:absolute;left:0;right:0;top:100%;background:#fff;border-bottom:1px solid var(--rule)}
  nav.main.open{display:block}
  nav.main ul{flex-direction:column;gap:0;padding:8px 28px 20px}
  nav.main a{display:block;padding:12px 0;font-size:17px}
  .menu-toggle{display:inline-block}
  header.site .btn{display:none}
  .head,.catalog,.about,.contact{grid-template-columns:1fr;gap:36px}
  .brands .wrap{grid-template-columns:1fr;gap:14px}
  section.block{padding:72px 0}
}
@media (max-width:560px){
  .wrap{padding:0 20px}
  .brand img{height:34px}
  .hero{padding-top:56px}
  .bead-wrap{margin-top:56px}
  .catalog .row{grid-template-columns:1fr;gap:2px}
  .parts{grid-template-columns:1fr}
  .info div{grid-template-columns:1fr;gap:2px}
  .topbar .tel{display:none}
}
@media (prefers-reduced-motion:reduce){
  .bead-wrap{animation:none}
  html{scroll-behavior:auto}
}
</style>
</head>
<body>

<div class="topbar">
  <div class="wrap">
    <a class="tel" href="tel:+622126071148">+62 21 2607 1148</a>
    <div class="lang" role="group" aria-label="Language">
      <button type="button" data-set="id" aria-pressed="true">ID</button>
      <button type="button" data-set="en" aria-pressed="false">EN</button>
      <button type="button" data-set="ko" aria-pressed="false">한국어</button>
      <button type="button" data-set="ja" aria-pressed="false">日本語</button>
    </div>
  </div>
</div>

<header class="site">
  <div class="wrap">
    <a class="brand" href="#top"><img src="data:image/png;base64," alt="PT. SNI" width="487" height="142"></a>
    <nav class="main" id="nav" aria-label="Menu">
      <ul>
        <li><a href="#produk"><span data-i18n="nav.products">Produk</span></a></li>
        <li><a href="#pembangkit"><span data-i18n="nav.power">Pembangkit Listrik</span></a></li>
        <li><a href="#industri"><span data-i18n="nav.industries">Industri</span></a></li>
        <li><a href="#tentang"><span data-i18n="nav.about">Tentang Kami</span></a></li>
        <li><a href="#kontak"><span data-i18n="nav.contact">Kontak</span></a></li>
      </ul>
    </nav>
    <a class="btn btn-solid" href="#kontak"><span data-i18n="cta.quote">Minta penawaran</span></a>
    <button class="menu-toggle" type="button" aria-expanded="false" aria-controls="nav">Menu</button>
  </div>
</header>

<main id="top">

  <section class="hero">
    <div class="wrap">
      <h1><span data-i18n="hero.title">Material Las Terbaik untuk Aplikasi Khusus</span></h1>
      <p class="lead"><span data-i18n="hero.lead">Kawat las khusus, peralatan industri, dan suku cadang pembangkit listrik untuk pabrik, galangan kapal, dan proyek industri di seluruh Indonesia. Berkantor di LTC Glodok, Jakarta, sejak 2007.</span></p>
      <div class="actions">
        <a class="btn btn-solid" href="#kontak"><span data-i18n="cta.quote">Minta penawaran</span></a>
        <a class="btn btn-line" href="#produk"><span data-i18n="cta.products">Lihat produk</span></a>
      </div>
    </div>
    <div class="bead-wrap" aria-hidden="true">
      <svg xmlns="http://www.w3.org/2000/svg" width="100%" height="64">
        <defs>
          <linearGradient id="tint" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stop-color="#2F5E9E" stop-opacity="0"/>
            <stop offset=".14" stop-color="#2F5E9E" stop-opacity=".55"/>
            <stop offset=".27" stop-color="#5B4A94" stop-opacity=".8"/>
            <stop offset=".37" stop-color="#A8683A"/>
            <stop offset=".45" stop-color="#D8A64A"/>
            <stop offset=".55" stop-color="#D8A64A"/>
            <stop offset=".63" stop-color="#A8683A"/>
            <stop offset=".73" stop-color="#5B4A94" stop-opacity=".8"/>
            <stop offset=".86" stop-color="#2F5E9E" stop-opacity=".55"/>
            <stop offset="1" stop-color="#2F5E9E" stop-opacity="0"/>
          </linearGradient>
          <linearGradient id="metal" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stop-color="#7C8894"/>
            <stop offset=".3" stop-color="#DDE3E8"/>
            <stop offset=".55" stop-color="#AEB8C1"/>
            <stop offset="1" stop-color="#58636E"/>
          </linearGradient>
          <pattern id="ripple" width="10" height="64" patternUnits="userSpaceOnUse">
            <path d="M1 19 Q11 32 1 45" fill="none" stroke="#FFFFFF" stroke-opacity=".7" stroke-width="1.3"/>
            <path d="M3.2 19 Q13.2 32 3.2 45" fill="none" stroke="#2A333C" stroke-opacity=".35" stroke-width="1.1"/>
          </pattern>
        </defs>
        <rect x="0" y="4" width="100%" height="56" fill="url(#tint)"/>
        <rect x="0" y="19" width="100%" height="26" rx="13" fill="url(#metal)"/>
        <rect x="0" y="19" width="100%" height="26" fill="url(#ripple)"/>
      </svg>
    </div>
  </section>

  <section class="brands" aria-label="Brands">
    <div class="wrap">
      <p><span data-i18n="brands.label">Distributor resmi</span></p>
      <ul><li>NICHIA</li><li>Nikkei Aluminium</li><li>KISWEL</li><li>Hyundai Welding</li><li>Harris</li><li>Kennametal</li></ul>
    </div>
  </section>

  <section class="block" id="produk">
    <div class="wrap">
      <div class="head">
        <h2><span data-i18n="products.title">Produk</span></h2>
        <p><span data-i18n="products.lead">Dari elektroda baja karbon sampai paduan nikel dan titanium, ditambah peralatan dan material pendukung untuk bengkel dan lokasi proyek.</span></p>
      </div>
      <div class="catalog">
        <div>
          <h3><span data-i18n="cons.title">Bahan las</span></h3>
          <dl>
<div class="row"><dt><span data-i18n="c1.t">Baja karbon &amp; kekuatan tinggi</span></dt><dd><span data-i18n="c1.d">Termasuk baja paduan rendah untuk struktur dan bejana tekan</span></dd></div>
<div class="row"><dt><span data-i18n="c2.t">Baja tahan karat</span></dt><dd><span data-i18n="c2.d">Stainless, duplex, dan super duplex</span></dd></div>
<div class="row"><dt><span data-i18n="c3.t">Hardfacing</span></dt><dd><span data-i18n="c3.d">Lapisan tahan aus untuk komponen &amp; cetakan</span></dd></div>
<div class="row"><dt><span data-i18n="c4.t">Baja tahan panas</span></dt><dd><span data-i18n="c4.d">Untuk boiler, pipa uap, dan suhu tinggi</span></dd></div>
<div class="row"><dt><span data-i18n="c5.t">Besi cor</span></dt><dd><span data-i18n="c5.d">Perbaikan komponen besi cor</span></dd></div>
<div class="row"><dt><span data-i18n="c6.t">Logam non-besi</span></dt><dd><span data-i18n="c6.d">Nikel, tembaga, aluminium, dan titanium</span></dd></div>
<div class="row"><dt><span data-i18n="c7.t">Brazing &amp; thermal spray</span></dt><dd><span data-i18n="c7.d">Termasuk kawat untuk micro laser welding</span></dd></div>
          </dl>
        </div>
        <div class="single">
          <h3><span data-i18n="tools.title">Peralatan &amp; material</span></h3>
          <dl>
<div class="row"><dt><span data-i18n="t1.t">Aksesori &amp; mesin las</span></dt></div>
<div class="row"><dt><span data-i18n="t2.t">Mesin &amp; perkakas</span></dt><dd><span data-i18n="t2.d">Kompresor, generator, perkakas tangan</span></dd></div>
<div class="row"><dt><span data-i18n="t3.t">Alat ukur</span></dt></div>
<div class="row"><dt><span data-i18n="t4.t">Keselamatan industri</span></dt><dd><span data-i18n="t4.d">Perlengkapan pemadam kebakaran dan keselamatan</span></dd></div>
<div class="row"><dt><span data-i18n="t5.t">Material baja</span></dt><dd><span data-i18n="t5.d">Pelat baja, H-beam, scaffolding</span></dd></div>
<div class="row"><dt><span data-i18n="t6.t">Peralatan angkat &amp; angkut</span></dt></div>
          </dl>
        </div>
      </div>
    </div>
  </section>

  <section class="block" id="pembangkit">
    <div class="wrap">
      <div class="head">
        <h2><span data-i18n="pp.title">Suku cadang pembangkit listrik</span></h2>
        <p><span data-i18n="pp.lead">Kami memasok suku cadang tahan aus untuk coal mill dan boiler PLTU. Setara spesifikasi OEM, diproduksi di Korea &amp; Jepang, dengan koordinasi langsung dari Jakarta.</span></p>
      </div>
      <h3><span data-i18n="pp.parts">Komponen yang kami pasok</span></h3>
      <ul class="parts">
<li><b>Roll tire</b><span><span data-i18n="sub.mill">Coal mill</span></span></li>
<li><b>Table liner</b><span><span data-i18n="sub.mill">Coal mill</span></span></li>
<li><b>Throat ring</b><span><span data-i18n="sub.mill">Coal mill</span></span></li>
<li><b>Dynamic classifier</b><span><span data-i18n="sub.mill">Coal mill</span></span></li>
<li><b><span data-i18n="p.plate">Pelat hardfacing</span></b><span>Chromium carbide overlay</span></li>
<li><b><span data-i18n="p.pipe">Pipa overlay</span></b><span><span data-i18n="p.pipe.s">Jalur transport batu bara</span></span></li>
<li><b><span data-i18n="p.ceramic">Pelapis keramik</span></b><span><span data-i18n="p.ceramic.s">Perlindungan aus &amp; benturan</span></span></li>
<li><b><span data-i18n="p.spray">Pelapisan thermal spray</span></b><span><span data-i18n="p.spray.s">Tube boiler, anti oksidasi &amp; korosi</span></span></li>
      </ul>
    </div>
  </section>

  <section class="block" id="industri">
    <div class="wrap">
      <div class="head">
        <h2><span data-i18n="ind.title">Industri yang kami layani</span></h2>
        <p><span data-i18n="ind.lead">Pelanggan kami mulai dari bengkel fabrikasi dan produsen komponen hingga BUMN dan grup industri besar.</span></p>
      </div>
      <p class="hint"><span data-i18n="ind.hint">Pilih sektor untuk melihat pelanggan kami</span></p>
      <ul class="sectors">
<li><button type="button" class="sector" data-sector="power" aria-pressed="true"><span data-i18n="s.power">Pembangkit listrik</span></button></li>
<li><button type="button" class="sector" data-sector="auto" aria-pressed="false"><span data-i18n="s.auto">Otomotif</span></button></li>
<li><button type="button" class="sector" data-sector="ship" aria-pressed="false"><span data-i18n="s.ship">Galangan kapal</span></button></li>
<li><button type="button" class="sector" data-sector="petro" aria-pressed="false"><span data-i18n="s.petro">Petrokimia</span></button></li>
<li><button type="button" class="sector" data-sector="steel" aria-pressed="false"><span data-i18n="s.steel">Baja</span></button></li>
<li><button type="button" class="sector" data-sector="mining" aria-pressed="false"><span data-i18n="s.mining">Pertambangan</span></button></li>
<li><button type="button" class="sector" data-sector="cement" aria-pressed="false"><span data-i18n="s.cement">Semen</span></button></li>
<li><button type="button" class="sector" data-sector="pulp" aria-pressed="false"><span data-i18n="s.pulp">Pulp &amp; kertas</span></button></li>
<li><button type="button" class="sector" data-sector="palm" aria-pressed="false"><span data-i18n="s.palm">Kelapa sawit</span></button></li>
<li><span class="sector static"><span data-i18n="s.sugar">Gula</span></span></li>
<li><span class="sector static"><span data-i18n="s.rubber">Karet</span></span></li>
      </ul>
