  }
  langBtns.forEach(function(b){b.addEventListener('click',function(){setLang(b.dataset.set)})});
  sectorBtns.forEach(function(b){b.addEventListener('click',function(){
    sector=b.dataset.sector;
    sectorBtns.forEach(function(x){x.setAttribute('aria-pressed',x===b?'true':'false')});
    renderClients();
  })});
  var saved=null;
  try{saved=localStorage.getItem('sni-lang')}catch(e){}
  if(saved&&DICT[saved]) setLang(saved);

  var t=document.querySelector('.menu-toggle'),nav=document.getElementById('nav');
  t.addEventListener('click',function(){
    var o=nav.classList.toggle('open');
    t.setAttribute('aria-expanded',o?'true':'false');
  });
  nav.querySelectorAll('a').forEach(function(a){a.addEventListener('click',function(){
    nav.classList.remove('open');t.setAttribute('aria-expanded','false');
  })});
})();
</script>
</body>
</html>
